import torch
import torchvision.transforms as transforms
import random

class SymmetricAugmenter:
    def __init__(self):
        # Sample uniformly from the C4 group {0, 90, 180, 270} degrees.
        # This preserves 90-degree rotation invariance.
        def rotate_x(x):
            angle = random.choice([0, 90, 180, 270])
            return transforms.functional.rotate(x, angle, resample=transforms.functional.InterpolationMode.BILINEAR)

        self.transform = transforms.Compose([
            transforms.Lambda(rotate_x),
        ])

    def augment(self, x: torch.Tensor) -> torch.Tensor:
        return self.transform(x)
